"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ArrowLeft, ArrowRight } from "lucide-react";

type Testimonial = {
  id: number;
  content: string;
  author: string;
  role: string;
  avatar: string;
  logo: React.ReactNode;
};

const MOCK_TESTIMONIALS: Testimonial[] = [
  {
    id: 1,
    content:
      "Ulka studio was super fun to work with. Not only we got our job done at a super affordable rate, we also got our app delivered before the deadline.",
    author: "Tim Bishop",
    role: "CEO, Lotus Minds",
    avatar: "https://i.pravatar.cc/150?u=1",
    logo: (
      <svg
        width="40"
        height="40"
        viewBox="0 0 40 40"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        className="text-black"
      >
        <path
          d="M10 20H30M10 20L20 10M10 20L20 30"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        {/* Replace with actual logo if needed */}
        <rect width="20" height="15" x="5" y="10" stroke="currentColor" strokeWidth="2" fill="none" />
        <rect width="20" height="15" x="15" y="15" stroke="currentColor" strokeWidth="2" fill="none" />
      </svg>
    ),
  },
  {
    id: 2,
    content:
      "The team was incredibly responsive and delivered a product that exceeded our expectations. I highly recommend them for any design needs.",
    author: "Sarah Jenkins",
    role: "Founder, TechFlow",
    avatar: "https://i.pravatar.cc/150?u=2",
    logo: (
      <svg
        width="40"
        height="40"
        viewBox="0 0 40 40"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
      >
        <circle cx="20" cy="20" r="10" stroke="currentColor" strokeWidth="2" fill="none" />
      </svg>
    ),
  },
  {
    id: 3,
    content:
      "A seamless experience from start to finish. They truly understand how to build beautiful, functional interfaces.",
    author: "Michael Chang",
    role: "Product Manager, Innovate",
    avatar: "https://i.pravatar.cc/150?u=3",
    logo: (
      <svg
        width="40"
        height="40"
        viewBox="0 0 40 40"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
      >
        <polygon points="20,10 30,30 10,30" stroke="currentColor" strokeWidth="2" fill="none" />
      </svg>
    ),
  },
];

export function StackedTestimonials({
  testimonials = MOCK_TESTIMONIALS,
}: {
  testimonials?: Testimonial[];
}) {
  const [currentIndex, setCurrentIndex] = useState(0);

  const handleNext = () => {
    setCurrentIndex((prevIndex) => (prevIndex + 1) % testimonials.length);
  };

  const handlePrev = () => {
    setCurrentIndex((prevIndex) =>
      prevIndex === 0 ? testimonials.length - 1 : prevIndex - 1
    );
  };

  // Helper to get visible cards in correct order
  const getVisibleCards = () => {
    const cards = [];
    for (let i = 0; i < 3; i++) {
      const index = (currentIndex + i) % testimonials.length;
      cards.push({ item: testimonials[index], offset: i });
    }
    // Reverse so the active card (offset 0) is rendered last / on top
    return cards.reverse();
  };

  return (
    <div className="w-full max-w-2xl mx-auto py-12 px-4 sm:px-6">
      <div className="mb-8">
        <h2 className="text-sm font-medium text-gray-500 mb-2">Testimonials</h2>
        <h3 className="text-3xl font-semibold text-gray-900 leading-tight">
          See what our clients are <br className="hidden sm:block" />
          saying about us.
        </h3>
      </div>

      <div className="relative bg-[#F4F4F6] rounded-3xl p-6 sm:p-10 h-[400px] flex items-center justify-center overflow-hidden">
        {/* Navigation Arrows */}
        <div className="absolute top-6 left-6 z-20">
          <button
            onClick={handlePrev}
            className="w-12 h-12 flex items-center justify-center bg-white rounded-full shadow-sm hover:shadow-md transition-shadow"
            aria-label="Previous testimonial"
          >
            <ArrowLeft className="w-5 h-5 text-gray-700" />
          </button>
        </div>
        <div className="absolute top-6 right-6 z-20">
          <button
            onClick={handleNext}
            className="w-12 h-12 flex items-center justify-center bg-white rounded-full shadow-sm hover:shadow-md transition-shadow"
            aria-label="Next testimonial"
          >
            <ArrowRight className="w-5 h-5 text-gray-700" />
          </button>
        </div>

        {/* Stacked Cards Container */}
        <div className="relative w-full max-w-[480px] h-[280px]">
          <AnimatePresence mode="popLayout">
            {getVisibleCards().map(({ item, offset }) => {
              const isTop = offset === 0;

              return (
                <motion.div
                  key={item.id}
                  layoutId={`testimonial-card-${item.id}`}
                  initial={{
                    opacity: 0,
                    scale: 0.9,
                    y: 20,
                  }}
                  animate={{
                    opacity: 1 - offset * 0.15,
                    scale: 1 - offset * 0.05,
                    y: offset * 12,
                    zIndex: 10 - offset,
                  }}
                  exit={{
                    opacity: 0,
                    scale: 0.9,
                    y: -20,
                  }}
                  transition={{
                    duration: 0.4,
                    ease: "easeInOut",
                  }}
                  className="absolute inset-0 bg-white rounded-2xl shadow-[0_8px_30px_rgb(0,0,0,0.04)] border border-gray-100 p-8 flex flex-col justify-between"
                  style={{
                    transformOrigin: "bottom center",
                  }}
                >
                  <div className="mb-6">
                    <div className="mb-4 h-8 flex items-center">
                      {item.logo}
                    </div>
                    <p className="text-gray-700 text-lg leading-relaxed font-medium">
                      "{item.content}"
                    </p>
                  </div>

                  <div className="flex items-center gap-3">
                    <img
                      src={item.avatar}
                      alt={item.author}
                      className="w-10 h-10 rounded-full object-cover grayscale"
                    />
                    <div>
                      <div className="font-semibold text-gray-900 text-sm">
                        {item.author}
                      </div>
                      <div className="text-gray-500 text-xs">{item.role}</div>
                    </div>
                  </div>
                </motion.div>
              );
            })}
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
}
